import itertools
import json

def build_itinerary():
    # Input constraints
    total_days = 17
    required_days = {"Naples": 5, "Vienna": 7, "Vilnius": 7}
    cities = ["Naples", "Vienna", "Vilnius"]
    # Direct flights (bidirectional)
    direct_flights = {
        ("Naples", "Vienna"), ("Vienna", "Naples"),
        ("Vienna", "Vilnius"), ("Vilnius", "Vienna")
    }
    # Special window: full Naples stay must be within Day 1-5 (inclusive)
    naples_window = (1, 5)

    # Helper: check if a sequence is connected by direct flights
    def is_valid_order(order):
        for i in range(len(order) - 1):
            if (order[i], order[i + 1]) not in direct_flights:
                return False
        return True

    # Build schedule with maximal overlaps (1 day overlap at each transition)
    # Start the itinerary on Day 1
    def schedule_for_order(order):
        start_day = 1
        segments = []
        current_start = start_day
        for idx, city in enumerate(order):
            if idx == 0:
                s = current_start
            else:
                s = segments[-1][2]  # overlap on transition day
            e = s + required_days[city] - 1
            segments.append((city, s, e))
        # Unique days consumed end at the last segment's end day
        final_day = segments[-1][2]
        return segments, final_day

    # Validate a schedule against constraints
    def validate_schedule(segments, final_day):
        # Total unique days must match
        if final_day != total_days:
            return False
        # Naples window constraint: entire 5-day stay must be within Day 1-5 inclusive
        for city, s, e in segments:
            if city == "Naples":
                if not (s >= naples_window[0] and e <= naples_window[1]):
                    return False
        return True

    # Try all valid orders and pick the first schedule satisfying constraints
    sum_required = sum(required_days[c] for c in cities)
    # Check feasibility: sum_required - (n-1) must equal total_days for full-overlap plan
    if sum_required - (len(cities) - 1) != total_days:
        raise ValueError("Constraints infeasible with given total days and required stays.")

    for order in itertools.permutations(cities):
        if not is_valid_order(order):
            continue
        segments, final_day = schedule_for_order(order)
        if validate_schedule(segments, final_day):
            itinerary = []
            for city, s, e in segments:
                itinerary.append({
                    "day_range": f"Day {s}-{e}",
                    "place": city
                })
            return {"itinerary": itinerary}

    raise ValueError("No valid itinerary found under the provided constraints.")

if __name__ == "__main__":
    result = build_itinerary()
    print(json.dumps(result))
